<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import type {PlayState} from '../../../api/src/rules/play-state';
import type {CharacterDataV2} from '../types/character';
import {vampireStatus,vampireTalent} from '../../../api/src/rules/live-vampire';
import {natureResourceProfile,natureResourceIds,mageSpellPlan,daemonSpectrumPlan} from '../../../api/src/rules/live-nature-resources';
import {adrenalineOptions} from '../../../api/src/rules/live-reality';
import {mageAmplitudes,mageMasteries} from '../../../api/src/rules/truth/mage-techniques';
import {truthPowers,powerAllowed} from '../../../api/src/rules/play-truth';
import {frenzyPowerIds} from '../../../api/src/rules/live-frenzy';
import {registeredTruthPowers,explicitPower,type RegisteredPowerRule} from '../../../api/src/rules/live-power-registry';

const props=defineProps<{data:CharacterDataV2;state:PlayState;profile:any;canEdit:boolean;busy:boolean;inCombat:boolean;manager?:boolean;section?:'all'|'truth'|'equipment'|'effects'}>();
const emit=defineEmits<{action:[action:string,payload:Record<string,unknown>]}>();
const blocked=computed(()=>props.busy||!props.canEdit);
const showTruth=computed(()=>!props.section||props.section==='all'||props.section==='truth');
const showEquipment=computed(()=>!props.section||props.section==='all'||props.section==='equipment');
const showEffects=computed(()=>!props.section||props.section==='all'||props.section==='effects');
const live=computed(()=>props.state as any);
const vampire=computed(()=>vampireStatus(props.data,props.state));
const resources=computed(()=>natureResourceProfile(props.data,props.state,props.profile.skills?.find((s:any)=>s.id==='force_mentale')?.rank??0));
const boosts=computed(()=>adrenalineOptions(props.data,props.state));
const effects=computed<any[]>(()=>Array.isArray(live.value.effects)?live.value.effects:[]);
const stasisHours=ref(1),stasisRegenerable=ref(false),openAuraBoost=ref(false),weakness=ref(''),anchorHours=ref(1);
const anchorRestoreHours=ref(24),anchorBodyRepairable=ref(false),anchorPractitioner=ref(false);
const vampCapabilities=computed(()=>({yang:vampireTalent(props.data,props.state,'souffle_du_yang'),union:vampireTalent(props.data,props.state,'union_du_hun_et_du_po'),anchor:vampireTalent(props.data,props.state,'sang_preserve')}));
const registered=computed(()=>registeredTruthPowers(props.data,props.state)),registeredId=ref(''),contextConfirmed=ref(false),registeredSkill=ref('');
const selectedRegistered=computed(()=>registered.value.find(p=>p.id===registeredId.value));
const preparedPowers=computed<any[]>(()=>(live.value.registeredPowers??[]).filter((p:any)=>p.until===null||p.until>=props.state.round));
const selectedPrepared=computed(()=>preparedPowers.value.some(p=>p.id===registeredId.value));
const routeNames:Record<string,string>={activate:'Activer sur mon personnage',roll:'À sélectionner pour un jet',attack:'À sélectionner pour une attaque',defense:'À sélectionner pour une défense',damage:'À appliquer à la résolution des dégâts',heal:'À appliquer aux soins',passive:'Effet permanent ou automatique',external:'À résoudre avec le MJ'};
function skillOptions(rule:RegisteredPowerRule){const effects=rule.effects.filter(e=>e.kind==='skill');return (props.profile.skills??[]).filter((s:any)=>effects.every(e=>!e.skills||e.skills.includes(s.id)));}
const needsSkill=computed(()=>selectedRegistered.value?.effects.some(e=>e.kind==='skill'&&(!e.skills||e.skills.length>1))??false);
watch(registered,rows=>{if(!rows.some(p=>p.id===registeredId.value))registeredId.value=rows[0]?.id??'';},{immediate:true});
watch(()=>[selectedRegistered.value?.id,props.state.revelation,props.state.form].join('|'),()=>{const rule=selectedRegistered.value;contextConfirmed.value=false;registeredSkill.value=rule?skillOptions(rule)[0]?.id??'':'';},{immediate:true});
function activateRegistered(){if(!selectedRegistered.value)return;act(selectedRegistered.value.route==='restricted'?'restricted-power-activate':'power-activate',{powerId:selectedRegistered.value.id,contextConfirmed:contextConfirmed.value,...(needsSkill.value?{skill:registeredSkill.value}:{})});}
const durationNames=(duration:string|number)=>typeof duration==='number'?`Fin du round ${Math.max(props.state.round,props.state.round+duration-1)}`:duration==='test'?'Prochain test éligible':duration==='scene'?'Fin de scène':'Fin de scénario';
const limitNames:Record<string,string>={round:'1/round',scene:'1/scène',day:'1/jour',scenario:'1/scénario'};
function registeredEffect(e:any){const name=({skill:'aux tests concernés',damage:'aux dégâts',armor:'Armure',reduction:'Réduction',healing:'PV',pa:'PA',piercing:'Pénétration'} as Record<string,string>)[e.kind]??e.kind;return `${e.mode==='replace'?'Valeur ':e.amount>=0?'+':''}${e.amount} ${name}`;}
const mageAffinity=ref(''),mageAmplitude=ref('mineure'),mageRange=ref('contact'),mageChannel=ref(0),mageInvest=ref(1);
const mageIntent=ref('narrative'),mageOpposed=ref(false),mageUrgent=ref(false),mageDifficult=ref(false),mageForceAmplitude=ref(false),mageForceMastery=ref(false),mageNote=ref('');
watch(mageIntent,intent=>{if(intent==='hostile')mageOpposed.value=true;});
const powerInvest=ref(1),favorNote=ref(''),favorSkill=ref('athletisme'),bladeSacrifice=ref(1);
const powerPreparation=computed(()=>resources.value.resources.powerPreparation);
const offeringAvailable=computed(()=>angelus.value?.hasOffering??false);
const bladeAvailable=computed(()=>angelus.value?.canBlade||angelus.value?.bladeHp>0);
const reality=computed(()=>props.profile.reality);
const neuroSelected=ref<string[]>([]),neuroSafeRestart=ref(false),manualAura=ref(0);
const neuroAvailableCapacity=computed(()=>reality.value?.neuro?.availableCapacity??reality.value?.neuro?.capacity??0);
const neuroBurnedSlots=computed(()=>Math.max(new Set<string>(live.value.neuroBurned??[]).size,(reality.value?.neuro?.capacity??0)-neuroAvailableCapacity.value));
watch(()=>[...(live.value.neuroBurned??[])].sort().join('|'),()=>{neuroSafeRestart.value=false;});
function rebootNeuro(){if(!props.inCombat&&neuroSafeRestart.value&&neuroBurnedSlots.value>0)act('reality-neuro-reboot',{safeRestart:true});}
const chargedWeapons=computed<any[]>(()=>reality.value?.chargedWeapons??[]),ammoWeaponId=ref(''),ammoRemaining=ref(0),ammoReserve=ref<number|null>(null),ammoAvailable=ref(false);
const weaponUid=(weapon:any)=>String(weapon.weaponId??weapon.inventoryUid??weapon.inventoryUID??weapon.uid??weapon.id);
const chosenAmmoWeapon=computed(()=>chargedWeapons.value.find(w=>weaponUid(w)===ammoWeaponId.value));
watch(chargedWeapons,rows=>{if(!rows.some(w=>weaponUid(w)===ammoWeaponId.value))ammoWeaponId.value=rows[0]?weaponUid(rows[0]):'';},{immediate:true});
watch(()=>[ammoWeaponId.value,chosenAmmoWeapon.value?.remaining,chosenAmmoWeapon.value?.reserve].join('|'),()=>{ammoRemaining.value=chosenAmmoWeapon.value?.remaining??0;ammoReserve.value=chosenAmmoWeapon.value?.reserve??null;ammoAvailable.value=false;},{immediate:true});
function declareMagazine(){act('reality-magazine',{weaponId:ammoWeaponId.value,remaining:ammoRemaining.value,...(ammoReserve.value!==null&&String(ammoReserve.value)!==''?{reserve:Number(ammoReserve.value)}:{})});}

const programId=(program:any)=>String(program.uid??program.itemId);
watch(()=>reality.value?.neuro?.loaded?.map(programId).join('|')??'',()=>{neuroSelected.value=(reality.value?.neuro?.loaded??[]).map(programId);},{immediate:true});
const amplitudes=[['mineure','Mineure'],['significative','Significative'],['majeure','Majeure'],['cataclysmique','Cataclysmique']];
const mage=computed<any>(()=>resources.value.nature==='mage'&&resources.value.enabled?(resources.value as any).mage:null);
const angelus=computed<any>(()=>resources.value.nature==='angelus'&&resources.value.enabled?(resources.value as any).angelus:null);
const daemon=computed<any>(()=>resources.value.nature==='daemon'&&resources.value.enabled?(resources.value as any).daemon:null);
watch(()=>angelus.value?.aura,value=>{manualAura.value=value??0;},{immediate:true});
const spellCaster=computed<any>(()=>mage.value||(daemon.value?.spectra?.length?{...resources.value.resources.mage,affinities:daemon.value.spectra,canCast:props.state.revelation==='r'&&!props.state.unconscious}:null));
const naturePowers=computed<any[]>(()=>((resources.value as any).powers??[]).filter((p:any)=>!registered.value.some(r=>r.id===p.id)));
const naturePowerId=ref('');
const chosenNaturePower=computed(()=>naturePowers.value.find(p=>p.id===naturePowerId.value));
watch(naturePowers,rows=>{if(!rows.some(p=>p.id===naturePowerId.value))naturePowerId.value=rows[0]?.id??'';},{immediate:true});
const affinities=computed<any[]>(()=>(spellCaster.value?.affinities??[]));
const chosenAffinity=computed<any>(()=>affinities.value.find(a=>a.id===mageAffinity.value));
watch(affinities,rows=>{if(!rows.some(a=>a.id===mageAffinity.value))mageAffinity.value=rows.find(a=>a.owned)?.id??rows[0]?.id??'';},{immediate:true});
function act(action:string,payload:Record<string,unknown>={}){if(!blocked.value)emit('action',action,{...(pursuesImpulse.value?{pursuesImpulse:true,contextConfirmed:true}:{}),...payload});}
const spellDraft=computed(()=>({intent:mageIntent.value,affinity:mageAffinity.value,amplitude:mageAmplitude.value,range:mageRange.value,channel:mageChannel.value,opposed:mageOpposed.value,urgent:mageUrgent.value,contextDifficult:mageDifficult.value,forceAmplitude:!!mage.value&&mageForceAmplitude.value,forceMastery:!!mage.value&&mageForceMastery.value,note:mageNote.value.trim()}));
const spellPreview=computed<{plan:ReturnType<typeof mageSpellPlan>|null;error:string}>(()=>{if(!spellCaster.value||!mageAffinity.value)return {plan:null,error:''};try{return {plan:(mage.value?mageSpellPlan:daemonSpectrumPlan)(props.data,props.state,spellDraft.value),error:''};}catch(cause){const code=cause instanceof Error?cause.message:'';return {plan:null,error:({spectrum_unavailable:'Ce Spectre exige l’état Révélé et une Affinité possédée.',spectrum_cannot_force:'Les Spectres ne permettent pas de forcer la Maîtrise ou l’Amplitude.',mageius_unavailable:'Mageius indisponible dans cet état.',spell_amplitude_unavailable:'Cette Amplitude dépasse la maîtrise disponible.',force_requires_owned_affinity:'Il faut posséder cette Affinité pour forcer sa Maîtrise ou son Amplitude.',invalid_superior_will:'Forcer exige le palier immédiatement supérieur à votre maîtrise.',mandatory_channel_missing:'Une canalisation supplémentaire est requise pour cette difficulté.',invalid_spell:'Vérifie la portée, l’Amplitude et la canalisation.'} as Record<string,string>)[code]??'Ce sort demande une vérification de ses conditions.'};}});
function spellAction(action:string,payload:Record<string,unknown>={}){act(`nature-${mage.value?'mage':'daemon-spectrum'}-${action}`,payload);}
function beginSpell(){if(spellPreview.value.plan)spellAction('begin',{spell:spellDraft.value,invest:mageInvest.value});}
const itemResources=computed(()=>props.profile.itemResources);
const ablativeItemId=ref(''),replacementAvailable=ref(false),truthReserveId=ref(''),truthReserveRemaining=ref(0),safeExitConfirmed=ref(false);
const chosenAblative=computed(()=>itemResources.value?.ablative?.find((item:any)=>item.id===ablativeItemId.value));
const chosenTruthReserve=computed(()=>itemResources.value?.weaponReserves?.find((item:any)=>item.id===truthReserveId.value));
const hasItemResources=computed(()=>itemResources.value?.ablative?.length||itemResources.value?.weaponReserves?.length||itemResources.value?.guards?.brigandine?.owned||itemResources.value?.guards?.token?.owned);
watch(()=>itemResources.value?.ablative,rows=>{if(!rows?.some((item:any)=>item.id===ablativeItemId.value))ablativeItemId.value=rows?.[0]?.id??'';},{immediate:true});
watch(()=>[ablativeItemId.value,chosenAblative.value?.remaining].join('|'),()=>{replacementAvailable.value=false;});
watch(()=>itemResources.value?.weaponReserves,rows=>{if(!rows?.some((item:any)=>item.id===truthReserveId.value))truthReserveId.value=rows?.[0]?.id??'';},{immediate:true});
watch(()=>[truthReserveId.value,chosenTruthReserve.value?.remaining].join('|'),()=>{truthReserveRemaining.value=chosenTruthReserve.value?.remaining??0;},{immediate:true});
watch(()=>[props.state.activation,(props.state.registeredPowers??[]).map(power=>power.id+':'+power.until).join('|')].join('|'),()=>{safeExitConfirmed.value=false;});
const frenzy=computed(()=>props.profile.frenzy),frenzyPowerId=ref(''),frenzyCause=ref(''),frenzyImpulse=ref(''),frenzyContext=ref(false),frenzyCauseGone=ref(false),frenzyExitContext=ref(false),pursuesImpulse=ref(false);
const frenzyCapabilities=computed(()=>truthPowers(props.data).filter(power=>frenzyPowerIds.has(power.id)));
watch(frenzyCapabilities,rows=>{if(!rows.some(power=>power.id===frenzyPowerId.value))frenzyPowerId.value=rows[0]?.id??'';},{immediate:true});
watch(()=>[frenzyPowerId.value,frenzyCause.value,frenzyImpulse.value],()=>{frenzyContext.value=false;});
watch(()=>[props.state.round,props.state.activation,frenzy.value?.active,frenzy.value?.impulseRequired,frenzy.value?.impulse].join('|'),()=>{pursuesImpulse.value=false;frenzyExitContext.value=false;});
const chosenFrenzy=computed(()=>frenzyCapabilities.value.find(power=>power.id===frenzyPowerId.value));
const imposedOrigin=ref('supernatural'),imposedSource=ref(''),imposedCause=ref(''),imposedImpulse=ref(''),imposedContext=ref(false),augmenticTrigger=ref(false),fearSource=ref(''),fearCause=ref(''),fearLevel=ref(1),fearContext=ref(false);
watch(()=>[imposedOrigin.value,imposedSource.value,imposedCause.value,imposedImpulse.value],()=>{imposedContext.value=false;augmenticTrigger.value=false;});
watch(()=>[fearSource.value,fearCause.value,fearLevel.value],()=>{fearContext.value=false;});
function enterFrenzy(){if(chosenFrenzy.value)act('frenzy-enter',{powerId:chosenFrenzy.value.id,cause:frenzyCause.value.trim(),impulse:frenzyImpulse.value.trim(),contextConfirmed:frenzyContext.value});}
function imposedFrenzy(action:string){act(action,{origin:imposedOrigin.value,sourceId:imposedSource.value.trim(),cause:imposedCause.value.trim(),impulse:imposedImpulse.value.trim(),contextConfirmed:imposedContext.value,...(action==='frenzy-augmentic-resist'?{triggerConfirmed:augmenticTrigger.value}:{})});}
const periodNames:Record<string,string>={'round-start':'début de round','round-end':'fin de round','activation-start':'début de l’activation','activation-end':'fin de l’activation'};
const scopeNames:Record<string,string>={physical:'tests physiques',mental:'tests mentaux',social:'tests sociaux',intellectual:'tests intellectuels',visual:'tests visuels',skill:'compétence', 'defense-physical':'défense physique','defense-neuro':'défense neuro','defense-occult':'défense occulte',armor:'armure',damage:'dégâts',reduction:'réduction de dégâts','pa-physical':'actions physiques',regeneration:'régénération',condition:'état'};
function expiry(e:any){if(e.expires?.unit==='round')return `Fin du round ${e.expires.at}`;if(e.expires?.unit==='activation')return `Fin de l’activation ${e.expires.at}`;if(e.expires?.unit==='scene')return 'Fin de scène';return 'Jusqu’à son retrait';}
function effectValue(e:any){if(e.kind==='condition')return e.scope==='pa-physical'?`${e.amount} PA physique(s) au maximum`:e.scope==='regeneration'?'Régénération bloquée':e.note||'Condition suivie';if(e.kind==='damage')return `${e.amount} dégâts${e.armorMode==='ignore'?' sans armure':''}`;if(e.kind==='healing')return `+${e.amount} PV`;return `${e.amount>=0?'+':''}${e.amount} · ${e.scope==='skill'?(props.profile.skills?.find((s:any)=>s.id===e.skill)?.name??'compétence'):scopeNames[e.scope]??'effet'}`;}
const summary=computed(()=>[showTruth.value&&mage.value?`Tension ${mage.value.tension}`:'',showTruth.value&&angelus.value?`Aura ${angelus.value.aura} / ${angelus.value.maximum}`:'',showTruth.value&&vampire.value.stasis?'En stase':'',showEffects.value&&effects.value.length?`${effects.value.length} effet${effects.value.length>1?'s':''}`:''].filter(Boolean).join(' · '));
const title=computed(()=>props.section==='truth'?'Ma Vérité en jeu':props.section==='equipment'?'Équipement actif & consommables':props.section==='effects'?'Effets & capacités préparées':'Ressources & effets en jeu');
const visible=computed(()=>showTruth.value&&(mage.value||angelus.value||daemon.value||vampire.value.available||vampire.value.stasis||vampire.value.anchor||registered.value.length||naturePowers.value.length||powerPreparation.value||frenzyCapabilities.value.length)||showEquipment.value&&(boosts.value.length||reality.value?.entries?.length||reality.value?.neuro?.owned?.length||neuroBurnedSlots.value||chargedWeapons.value.length||hasItemResources.value)||showEffects.value&&(effects.value.length||preparedPowers.value.length||frenzy.value?.active||frenzy.value?.fear||frenzy.value?.survivalFury||props.profile.lightningWounds?.blockedRegeneration||props.profile.lightningWounds?.finalDestruction||props.manager));
</script>
<template>
<details v-if="visible" class="live-mechanics" open>
  <summary><strong>{{title}}</strong><span v-if="summary">{{summary}}</span></summary>
  <div class="mechanics-content">
    <p v-if="!canEdit" class="read-only">Consultation de l’état actuel. Les commandes sont disponibles pour le propriétaire et le MJ.</p>
    <fieldset v-if="showTruth&&manager&&(mage||angelus||daemon)" :disabled="blocked" class="manager-resource-settings"><legend>MJ · conditions de la Vérité</legend><p>Ces conditions sont fixées par le MJ selon le lieu et la fiction ; elles ne sont pas déclarées par le joueur.</p><template v-if="mage"><label class="check"><input :checked="mage.dormant" type="checkbox" @change="act('nature-settings',{mageDormant:($event.target as HTMLInputElement).checked})" /> Mageius en sommeil</label><button :disabled="!mage.tension" @click="act('nature-settings',{clearTension:true})">Accalmie confirmée · remettre la Tension à zéro</button></template><template v-if="showTruth&&(angelus)"><label class="check"><input :checked="angelus.connected" type="checkbox" @change="act('nature-settings',{connected:($event.target as HTMLInputElement).checked})" /> Lien divin disponible</label><label class="check"><input :checked="angelus.holyPlace" type="checkbox" @change="act('nature-settings',{holyPlace:($event.target as HTMLInputElement).checked})" /> Lieu saint confirmé</label><div class="input-grid"><label>Réserve d’Aura à fixer<input v-model.number="manualAura" type="number" min="0" :max="angelus.maximum" /></label><button @click="act('nature-settings',{aura:manualAura})">Attribuer cette Aura</button></div></template><template v-if="showTruth&&(daemon)"><label class="check"><input :checked="daemon.resonancePlace" type="checkbox" @change="act('nature-settings',{resonancePlace:($event.target as HTMLInputElement).checked})" /> Lieu de résonance confirmé</label></template></fieldset>
    <div class="resource-grid">
      <fieldset v-if="showTruth&&(spellCaster)" :disabled="blocked" class="resource-card" :class="{'mage-resource':!!mage,'spectrum-resource':!mage}">
        <legend>{{mage?'Mageius · Tension & sort':'Spectres · Méphisto'}}</legend>
        <div v-if="mage" class="resource-totals"><strong>Tension {{spellCaster.tension}}</strong><span v-if="spellCaster.dormant">Mageius en sommeil</span><span v-if="spellCaster.pendingBacklash">Contrecoup à résoudre</span></div>
        <p>{{mage?'Les PA investis, la Tension et le résultat du test sont conservés avec le détail du sort.':'Les Spectres préparés gardent leur coût et leur test. Ils ne produisent ni Tension ni contrecoup de Mageius.'}}</p>
        <template v-if="spellCaster.preparation">
          <p class="preparation-status"><strong>Sort en préparation</strong><span>{{spellCaster.preparation.name}} · {{spellCaster.preparation.note}}</span></p>
          <p>{{spellCaster.preparation.paid}} / {{spellCaster.preparation.pa}} PA investis · difficulté {{spellCaster.preparation.difficulty}}<template v-if="mage"> · +{{spellCaster.preparation.tension}} Tension</template>.</p>
          <label>PA supplémentaires à investir<input v-model.number="mageInvest" type="number" min="1" max="20" /></label>
          <div class="button-row"><button @click="spellAction('invest',{amount:mageInvest})">Investir les PA</button><button :disabled="spellCaster.preparation.paid<spellCaster.preparation.pa" @click="spellAction('release')">Lancer le sort préparé</button><button class="secondary" @click="spellAction('cancel')">Abandonner le sort</button></div>
        </template>
        <form v-else @submit.prevent="beginSpell">
          <div class="input-grid"><label>Effet à résoudre<select v-model="mageIntent" aria-label="Intention du sort"><option value="narrative">Effet narratif</option><option value="support">Soutien / aide</option><option value="hostile">Effet hostile à résoudre</option></select></label><label>Affinité du sort<select v-model="mageAffinity" aria-label="Affinité du sort"><option v-for="a in affinities" :key="a.id" :value="a.id">{{a.name}}{{a.owned?' · maîtrisée':' · improvisation Initiale / Mineure'}}</option></select></label><label>Amplitude<select v-model="mageAmplitude" aria-label="Amplitude du sort"><option v-for="[id,label] in amplitudes" :key="id" :value="id">{{label}}</option></select></label><label>Portée<select v-model="mageRange"><option value="contact">Contact</option><option value="will">Portée de Volonté</option><option value="sight">Vue</option></select></label><label>Canalisation · PA supplémentaires<input v-model.number="mageChannel" type="number" min="0" max="100" /></label><label>PA investis au départ<input v-model.number="mageInvest" type="number" min="0" max="20" /></label></div>
          <p v-if="chosenAffinity" class="canonical-rule">{{chosenAffinity.description}}<span v-if="!chosenAffinity.owned"> Affinité non éveillée : improvisation limitée à Initiale / Mineure, difficulté augmentée d’un niveau.</span><span v-if="chosenAffinity.mastery>=0"> Maîtrise : {{mageMasteries[chosenAffinity.mastery as 0|1|2|3]?.name}}.</span><span v-if="chosenAffinity.amplitude>=0"> Amplitude maîtrisée : {{mageAmplitudes[chosenAffinity.amplitude as 0|1|2|3]?.name}}.</span></p>
          <div class="check-grid"><label><input v-model="mageOpposed" type="checkbox" :disabled="mageIntent==='hostile'" /> Sort en opposition</label><label><input v-model="mageUrgent" type="checkbox" /> Sort lancé dans l’urgence</label><label><input v-model="mageDifficult" type="checkbox" /> Contexte difficile</label><label v-if="mage"><input v-model="mageForceAmplitude" type="checkbox" /> Forcer l’Amplitude</label><label v-if="mage"><input v-model="mageForceMastery" type="checkbox" /> Forcer la Maîtrise</label></div>
          <label>Effet souhaité / cible<textarea v-model="mageNote" maxlength="500" rows="2" /></label>
          <p v-if="spellPreview.plan" class="spell-preview" role="status"><strong>{{spellPreview.plan.pa}} PA de préparation · difficulté {{spellPreview.plan.difficulty}}<template v-if="mage"> · +{{spellPreview.plan.tension}} Tension</template></strong><span v-if="spellPreview.plan.automatic">Réussite automatique dans les conditions déclarées.</span><span v-if="spellPreview.plan.forced">Volonté supérieure : contrecoup assuré à la libération.</span></p><p v-else-if="spellPreview.error" class="availability-note" role="status">{{spellPreview.error}}</p>
          <button type="submit" :disabled="!spellCaster.canCast||!mageAffinity||!spellPreview.plan">Préparer ce sort</button>
        </form>
        <div v-if="mage" class="button-row"><button class="secondary" :disabled="!inCombat||!spellCaster.tension||spellCaster.usedRound===state.round||!!spellCaster.preparation||!!spellCaster.maintained.length" @click="act('nature-mage-rest')">Un round entier sans Mageius · −1 Tension</button><button :disabled="!spellCaster.canDischarge" @click="act('nature-mage-discharge')">Décharge contrôlée · 1 PA · difficulté 15</button><button v-if="spellCaster.pendingBacklash" @click="act('nature-mage-backlash')">Résoudre le contrecoup</button></div>
      </fieldset>
      <fieldset v-if="showTruth&&(angelus)" :disabled="blocked" class="resource-card angelus-resource">
        <legend>Aura · Angelus</legend>
        <div class="resource-totals"><strong>{{angelus.aura}} / {{angelus.maximum}} Aura</strong><span>Rang {{angelus.rank}}</span></div>
        <p>{{angelus.connected?'Lien divin disponible.':'Lien divin indisponible.'}} {{angelus.holyPlace?'Lieu saint confirmé.':''}}</p>
        <label v-if="angelus.canBoost" class="check"><input v-model="openAuraBoost" type="checkbox" :disabled="angelus.boostUsed" /> Amplifier l’ouverture de l’Aura{{angelus.boostUsed?' · déjà utilisé':''}}</label>
        <div class="button-row"><button :disabled="!angelus.canOpen" @click="act('nature-angelus-open',{boost:openAuraBoost})">Ouvrir l’Auréole · 1 PA · +{{openAuraBoost?4:angelus.recharge}} Aura</button><button :disabled="inCombat||!angelus.canFill" @click="act('nature-angelus-fill')">Préparer la réserve avant la scène · {{angelus.maximum}} Aura</button></div>
        <div class="button-row"><button :disabled="state.revelation==='v'||angelus.aura<1||angelus.eyesActive||state.unconscious" @click="act('nature-angelus-eyes')">{{angelus.eyesActive?'Yeux célestes actifs':'Yeux célestes · 1 Aura'+(inCombat?' · 1 PA':'')}}</button><button :disabled="state.revelation!=='r'||angelus.aura<1||angelus.wingsActive||state.unconscious" @click="act('nature-angelus-wings')">{{angelus.wingsActive?'Ailes transcendées actives · +1 Agilité':'Ailes transcendées · 1 Aura · 1 PA'}}</button><button :disabled="state.revelation!=='r'||angelus.aura<1||state.unconscious" @click="act('nature-angelus-impulse')">Impulsion céleste · 1 Aura · Déplacement ×2</button></div><p v-if="angelus.egidePerAura">Égide : {{angelus.egidePerAura}} point(s) de protection par Aura investie. À choisir à la résolution d’une blessure spirituelle.</p>
        <button v-if="offeringAvailable" :disabled="angelus.aura>=angelus.maximum||profile.hp<=0||!!state.powerUses?.['round:'+natureResourceIds.offering]" @click="act('nature-angelus-offering')">Offrande vivante · 1 PV irréductible → 2 Aura · 1/round</button>
        <p v-if="angelus.offeringHp">{{angelus.offeringHp}} PV sacrifié(s) à l’Offrande, récupérables après la scène.</p>
        <template v-if="bladeAvailable"><template v-if="angelus.bladeHp"><p>Lame céleste active · DGT {{[0,7,9,11][angelus.bladeHp]}} · {{angelus.bladeHp}} PV réservés.</p><button class="secondary" @click="act('nature-angelus-dismiss-blade')">Dissiper la Lame céleste</button></template><template v-else><label>PV à réserver pour la Lame céleste<select v-model.number="bladeSacrifice"><option :value="1">1 PV · DGT 7</option><option :value="2">2 PV · DGT 9</option><option :value="3">3 PV · DGT 11</option></select></label><button :disabled="state.revelation!=='r'||angelus.aura<1||profile.hp<=bladeSacrifice" @click="act('nature-angelus-blade',{sacrifice:bladeSacrifice})">Incarner la Lame céleste · 1 PA · 1 Aura</button></template></template>
      </fieldset>
      <fieldset v-if="showTruth&&(daemon)" :disabled="blocked" class="resource-card daemon-resource">
        <legend>Faveur & résonance · Daemon</legend>
        <div class="resource-totals"><strong>{{daemon.favorUsed}} / {{daemon.favorLimit}} Faveur(s) utilisée(s)</strong></div>
        <p>{{daemon.resonancePlace?'Lieu de résonance confirmé par le MJ.':'Aucun lieu de résonance confirmé.'}}</p>
        <label>Compétence du prochain test<select v-model="favorSkill" aria-label="Compétence de la Faveur"><option v-for="skill in profile.skills" :key="skill.id" :value="skill.id">{{skill.name}}</option></select></label><label>Demande / bénéfice de la Faveur<textarea v-model="favorNote" rows="2" maxlength="500" /></label>
        <p v-if="daemon.pendingFavor">Faveur en attente : +3 au prochain test de {{profile.skills.find((s:any)=>s.id===daemon.pendingFavor.skill)?.name}} · {{daemon.pendingFavor.note}}.</p><button :disabled="!daemon.canFavor||!favorNote.trim()" @click="act('nature-daemon-favor',{note:favorNote.trim(),skill:favorSkill})">Faire appel à la Faveur</button>
      </fieldset>
      <fieldset v-if="showTruth&&(vampire.available||vampire.stasis||vampire.anchor)" :disabled="blocked" class="resource-card vampire-resource">
        <legend>Stase & Sang · Vampire</legend>
        <div class="resource-totals"><strong>{{vampire.stasis?'En stase':'Éveillé'}}</strong><span v-if="vampire.lastSleep">Dernier sommeil · {{vampire.lastSleepUsed?'utilisé ce scénario':'disponible'}}</span></div>
        <details><summary>Règles de la Stase & de la Prédation</summary><p>En stase, le Vampire ne réagit pas et n’agit pas. Les blessures ordinaires cessent de se dégrader spontanément.</p><p>La prédation utilise les dégâts réellement infligés à la cible, plafonnés par les blessures à récupérer. Aucun soin ne vient d’un simple jet d’attaque.</p></details>
        <button :disabled="!vampire.available||profile.hp<=0||(!vampire.stasis&&state.unconscious)" @click="act('vampire-stasis',{active:!vampire.stasis})">{{vampire.stasis?'Quitter la stase':'Entrer en stase'}}{{inCombat?(vampire.stasis?' · 1 PA':' · 2 PA'):''}}</button>
        <template v-if="vampire.stasis&&vampire.stasisRate"><p>{{vampire.stasisRate}} PV par heure en stase pour les blessures régénérables. Déclare le temps réellement écoulé.</p><div class="input-grid"><label>Heures passées en stase<input v-model.number="stasisHours" aria-label="Heures passées en stase" type="number" min="1" max="8760" /></label><label class="check"><input v-model="stasisRegenerable" type="checkbox" /> Blessures régénérables</label></div><button :disabled="inCombat||!stasisRegenerable" @click="act('vampire-stasis-recovery',{hours:stasisHours,regenerable:stasisRegenerable})">Récupérer +{{Math.max(0,Math.min((profile.healingMaximum??profile.derived.pvMax)-profile.hp,stasisHours*vampire.stasisRate))}} PV</button></template>
        <button v-if="vampire.surregime" :disabled="!inCombat||vampire.stasis||vampire.surregimeUsed||state.unconscious||profile.hp<=0||state.initiative===null" @click="act('vampire-surregime')">Surrégime · +1 PA ce round · {{vampire.surregimeUsed?'utilisé':'1/scène'}}</button>
        <template v-if="vampire.cycle"><p>Cycle du Sang : après s’être nourri, −1 PA au prochain Talent de Sang avant la fin du round.</p><button :disabled="!inCombat||!vampire.fedThisScene||vampire.cycleReady||vampire.stasis||!!state.powerUses?.['scene:trait:cycle-du-sang']" @click="act('vampire-cycle')">{{vampire.cycleReady?'Cycle du Sang prêt':'Préparer le Cycle du Sang · 0 PA · 1/scène'}}</button></template>
        <p v-if="vampire.exaltedBlood">Sang exalté : +3 au prochain jet lié à un Talent de Sang pendant cette scène.</p>
        <div v-if="vampCapabilities.yang||vampCapabilities.union" class="weakness-actions"><label>Faiblesse mineure concernée<input v-model="weakness" type="text" maxlength="120" placeholder="Faiblesse réellement possédée" /></label><p>Ces capacités exigent une prédation pendant la scène. Les conditions de la faiblesse restent à vérifier avec le MJ.</p><div class="button-row"><button v-if="vampCapabilities.yang" :disabled="!weakness.trim()||!vampire.fedThisScene||vampire.stasis||!!state.powerUses?.['scene:souffle_du_yang']" @click="act('vampire-yang',{weakness:weakness.trim()})">Souffle du Yang · 1 PA · 1/scène</button><button v-if="vampCapabilities.union" :disabled="!weakness.trim()||!vampire.fedThisScene||vampire.stasis||!!state.powerUses?.['scenario:union_du_hun_et_du_po']" @click="act('vampire-union',{weakness:weakness.trim()})">Union du Hun et du Po · 1 PA · 1/scénario</button></div></div>
        <p v-if="vampire.suppressedWeakness">Faiblesse suivie : {{vampire.suppressedWeakness.id}} · {{vampire.suppressedWeakness.mode==='half'?'dommages réduits de moitié':'ignorée'}}<template v-if="vampire.suppressedWeakness.untilRound!==null"> jusqu’au round {{vampire.suppressedWeakness.untilRound}}</template>.</p>
        <template v-if="vampCapabilities.anchor||vampire.anchor"><template v-if="vampire.anchor"><p>Ancrage sanguin préparé : 3 PV restent réservés. La restauration nécessite un corps réparable, un praticien et au moins 24 heures de rituel hors combat.</p><fieldset v-if="manager" class="anchor-manager"><legend>MJ · ancrage sanguin</legend><p v-if="!vampire.available">Le Vampire doit être Révélé pour résoudre son ancrage.</p><button class="secondary" :disabled="!vampire.available" @click="act('vampire-anchor-destroy')">Déclarer l’ancrage détruit</button><label>Heures du rituel de restauration accompli<input v-model.number="anchorRestoreHours" aria-label="Heures du rituel de restauration" type="number" min="24" max="8760" step="1" /></label><label class="check"><input v-model="anchorBodyRepairable" type="checkbox" /> Le corps est réparable</label><label class="check"><input v-model="anchorPractitioner" type="checkbox" /> Un praticien a accompli le rituel</label><p>Consomme l’ancrage et restaure le Vampire à 1 PV, stabilisé et inconscient en Stase.</p><button :disabled="!vampire.available||inCombat||profile.hp>profile.derived.death||!Number.isSafeInteger(anchorRestoreHours)||anchorRestoreHours<24||anchorRestoreHours>8760||!anchorBodyRepairable||!anchorPractitioner" @click="act('vampire-anchor-restore',{hours:anchorRestoreHours,bodyRepairable:anchorBodyRepairable,practitioner:anchorPractitioner})">Restauration Alghul · consommer l’ancrage</button></fieldset></template><template v-else><label>Temps du rituel d’ancrage, en heures<input v-model.number="anchorHours" type="number" min="1" max="8760" /></label><button :disabled="inCombat||vampire.stasis||profile.hp<=0" @click="act('vampire-anchor',{hours:anchorHours})">Sang préservé · réserver 3 PV</button></template></template>
      </fieldset>
      <fieldset v-if="showEquipment&&(boosts.length)" :disabled="blocked" class="resource-card reality-resource">
        <legend>Augmentations · Adrénaline</legend>
        <article v-for="boost in boosts" :key="boost.id" class="ability-row"><strong>{{boost.label}}</strong><p>+1 PA par round, maximum 4 PA, pendant {{boost.rounds}} round(s). À la fin : Stress temporaire {{boost.afterStress===2?'Paniqué':'Tendu'}}.</p><button :disabled="!boost.available||!inCombat" @click="act('reality-adrenaline',{implantId:boost.id})">{{boost.active?'Effet actif':boost.used?'Utilisé cette scène':'Activer · 0 PA · 1/scène'}}</button></article>
      </fieldset>
    </div>
    <fieldset v-if="showEquipment&&(reality?.entries?.length||reality?.neuro?.owned?.length||neuroBurnedSlots)" class="reality-metrics"><legend>Réalité · charge & Neuro</legend><div class="resource-totals" v-if="reality"><strong>Charge {{reality.charge}}</strong><strong>Stress augmentique {{reality.totalStress}}</strong><span>Stress brut {{reality.rawStress}} · réduction {{reality.reduction}}</span></div><p v-if="reality?.neuroDefenseBonus">Défense Neuro : +{{reality.neuroDefenseBonus}} par les augmentations actives.</p><p v-if="reality?.recoveryMultiplier>1">Récupération naturelle ×{{reality.recoveryMultiplier}} par les augmentations actives.</p><template v-if="reality.neuro?.owned?.length"><p>Programmes Neuro chargés : {{reality.neuro.loaded.length}} / {{neuroAvailableCapacity}} emplacements disponibles ({{reality.neuro.capacity}} au total).</p><p v-if="reality.neuro.unsinkable">L’accès au Neurodive est bloqué par Unsinkable.</p><p v-else-if="!reality.neuro.hasInterface">Une interface Neurodive compatible est requise.</p><p v-else-if="reality.neuro.overCapacity">Le nombre de programmes dépasse la capacité de chargement.</p><ul><li v-for="program in reality.neuro.loaded" :key="program.uid??program.itemId">{{program.item.name}}</li></ul><fieldset :disabled="blocked" class="neuro-loading"><legend>Programmes possédés à charger</legend><label v-for="program in reality.neuro.owned" :key="programId(program)" class="check"><input v-model="neuroSelected" type="checkbox" :value="programId(program)" :disabled="(live.neuroBurned??[]).includes(programId(program))" /> {{program.item.name}}<span v-if="(live.neuroBurned??[]).includes(programId(program))"> · indisponible</span></label><p>{{neuroSelected.length}} programme(s) choisi(s), {{neuroAvailableCapacity}} emplacement(s) disponible(s). {{inCombat?'Chargement sous pression : 1 PA.':'Chargement hors combat : 0 PA.'}}</p><button :disabled="neuroSelected.length>neuroAvailableCapacity||!reality.neuro.eligible" @click="act('reality-neuro-load',{programs:[...neuroSelected]})">Charger ces programmes{{inCombat?' · 1 PA':''}}</button></fieldset></template><fieldset v-if="neuroBurnedSlots" :disabled="blocked||inCombat" class="neuro-reboot"><legend>Neuro · redémarrage sûr</legend><p>{{neuroBurnedSlots}} emplacement(s) détruit(s) peuvent être récupérés après le combat, avec un redémarrage sûr. Aucune copie ni licence de programme n’est recréée ; les programmes possédés devront être rechargés.</p><p v-if="inCombat" role="status">Termine le combat avant de redémarrer le système Neuro.</p><label class="check"><input v-model="neuroSafeRestart" type="checkbox" /> Je confirme un redémarrage sûr, après la fin du combat Neuro</label><button :disabled="!neuroSafeRestart" @click="rebootNeuro">Redémarrer le Neuro · récupérer {{neuroBurnedSlots}} emplacement(s)</button></fieldset></fieldset>
    <details v-if="showEquipment&&hasItemResources" class="item-consumables"><summary>Protections & ressources de Vérité</summary><fieldset :disabled="blocked" class="item-protections" v-if="itemResources.ablative?.length"><legend>Protections ablatives</legend><label>Protection possédée<select v-model="ablativeItemId" aria-label="Protection ablative"><option v-for="item in itemResources.ablative" :key="item.id" :value="item.id">{{item.name}} · {{item.remaining}} / {{item.capacity}}</option></select></label><template v-if="chosenAblative"><p><strong>{{chosenAblative.remaining}} / {{chosenAblative.capacity}} impact(s) restant(s)</strong></p><p v-if="inCombat&&!manager">Le MJ peut confirmer le remplacement pendant le combat.</p><label class="check"><input v-model="replacementAvailable" type="checkbox" :disabled="inCombat&&!manager" /> Le remplacement ou la recharge a réellement été effectué</label><button :disabled="inCombat&&!manager||!replacementAvailable||chosenAblative.remaining>=chosenAblative.capacity" @click="act('reality-ablative-replace',{itemId:ablativeItemId,replacementAvailable})">Enregistrer le remplacement</button></template></fieldset><fieldset v-if="itemResources.weaponReserves?.length" :disabled="blocked||inCombat&&!manager" class="truth-reserves"><legend>Réserves réelles des armes de Vérité</legend><label>Arme possédée<select v-model="truthReserveId" aria-label="Réserve d’arme de Vérité"><option v-for="weapon in itemResources.weaponReserves" :key="weapon.id" :value="weapon.id">{{weapon.name}} · {{weapon.remaining===null?'non déclarée':weapon.remaining}}</option></select></label><p>Déclare uniquement la réserve réellement disponible.</p><label>Quantité disponible<input v-model.number="truthReserveRemaining" type="number" min="0" max="100000" /></label><button :disabled="!Number.isSafeInteger(truthReserveRemaining)||truthReserveRemaining<0" @click="act('reality-truth-reserve',{sourceId:truthReserveId,remaining:truthReserveRemaining})">Enregistrer cette réserve</button></fieldset><p v-if="itemResources.guards?.brigandine?.owned">Brigandine runique : {{itemResources.guards.brigandine.available?'protection disponible':'protection utilisée pour ce scénario'}}.</p><p v-if="itemResources.guards?.token?.owned">Jeton de Garde : {{itemResources.guards.token.remaining}} / {{itemResources.guards.token.owned}} disponible(s). Utilisable lors de la résolution d’une attaque surnaturelle.</p></details>
    <fieldset v-if="showEquipment&&(chargedWeapons.length)" :disabled="blocked" class="magazine-controls"><legend>Armes · chargeurs & munitions</legend><label>Arme possédée<select v-model="ammoWeaponId" aria-label="Arme à recharger"><option v-for="weapon in chargedWeapons" :key="weaponUid(weapon)" :value="weaponUid(weapon)">{{weapon.name??weapon.label}} · {{weapon.remaining}} / {{weapon.capacity}} charges</option></select></label><template v-if="chosenAmmoWeapon"><p><strong>{{chosenAmmoWeapon.remaining}} / {{chosenAmmoWeapon.capacity}} charges</strong><template v-if="chosenAmmoWeapon.reserve!==null&&chosenAmmoWeapon.reserve!==undefined"> · réserve {{chosenAmmoWeapon.reserve}}</template><template v-else> · réserve à déclarer</template>.</p><p>Une attaque de Tir simple consomme une charge au lancement du jet, même si elle échoue.</p><label class="check"><input v-model="ammoAvailable" type="checkbox" /> Je dispose des munitions compatibles pour cette recharge</label><button :disabled="!ammoAvailable||chosenAmmoWeapon.remaining>=chosenAmmoWeapon.capacity||chosenAmmoWeapon.reserve===0" @click="act('reality-reload',{weaponId:ammoWeaponId,ammunitionAvailable:ammoAvailable})">Recharger{{inCombat?' · 1 PA':' · hors combat'}}</button><details class="magazine-settings"><summary>{{manager?'Corriger le chargeur & la réserve':'Déclarer le chargeur hors combat'}}</summary><fieldset :disabled="blocked||inCombat&&!manager"><legend>{{manager?'MJ · état du chargeur et réserve':'Déclaration hors combat'}}</legend><div class="input-grid"><label>Charges actuellement présentes<input v-model.number="ammoRemaining" type="number" min="0" :max="chosenAmmoWeapon.capacity" /></label><label>Munitions en réserve (facultatif)<input v-model.number="ammoReserve" type="number" min="0" max="100000" /></label></div><button :disabled="ammoRemaining<0||ammoRemaining>chosenAmmoWeapon.capacity" @click="declareMagazine">Enregistrer le chargeur et la réserve</button></fieldset></details></template></fieldset>
    <fieldset v-if="showTruth&&(powerPreparation)" :disabled="blocked" class="nature-capabilities"><legend>Pouvoir en préparation</legend><strong>{{naturePowers.find(p=>p.id===powerPreparation?.id)?.name??'Capacité préparée'}}</strong><p>{{powerPreparation.paid}} / {{powerPreparation.pa}} PA investis · {{powerPreparation.aura}} Aura dépensée.</p><label>PA supplémentaires à investir<input v-model.number="powerInvest" type="number" min="1" :max="Math.max(1,powerPreparation.pa-powerPreparation.paid)" /></label><div class="button-row"><button :disabled="powerPreparation.paid>=powerPreparation.pa" @click="act('nature-power-invest',{amount:powerInvest})">Investir les PA</button><button :disabled="powerPreparation.paid<powerPreparation.pa" @click="act('nature-power-release')">Libérer le pouvoir préparé</button><button class="secondary" @click="act('nature-power-cancel')">Abandonner la préparation</button></div><p>Le coût est suivi ici. L’effet sur une cible et les décisions de fiction se résolvent avec le MJ.</p></fieldset>
    <fieldset v-if="showTruth&&(naturePowers.length)" :disabled="blocked" class="nature-capabilities">
      <legend>Capacités de nature</legend>
      <label>Capacité de nature<select v-model="naturePowerId" aria-label="Capacité de nature"><option v-for="power in naturePowers" :key="power.id" :value="power.id">{{power.name}}</option></select></label>
      <article v-if="chosenNaturePower" class="ability-row"><h4>{{chosenNaturePower.name}}</h4><p>{{chosenNaturePower.pa===null?'Effet permanent / progression':chosenNaturePower.pa+' PA'}}<template v-if="chosenNaturePower.aura"> · {{chosenNaturePower.aura}} Aura</template><template v-if="chosenNaturePower.limit"> · {{limitNames[chosenNaturePower.limit]}}</template></p><details><summary>Texte de la capacité</summary><p class="canonical-rule">{{chosenNaturePower.text}}</p></details><p v-if="chosenNaturePower.reason" class="availability-note">{{chosenNaturePower.reason}}</p><label v-if="chosenNaturePower.pa">PA à investir<input v-model.number="powerInvest" type="number" min="0" :max="chosenNaturePower.pa" /></label><button :disabled="!chosenNaturePower.available||!!powerPreparation" @click="act('nature-power',{id:chosenNaturePower.id,invest:Math.min(chosenNaturePower.pa??0,powerInvest)})">Utiliser {{chosenNaturePower.name}}</button></article>
    </fieldset>
    <fieldset v-if="showTruth&&(registered.length)" :disabled="blocked" class="registered-capabilities"><legend>Capacités · coûts & effets préparés</legend><label>Capacité à utiliser<select v-model="registeredId" aria-label="Capacité à utiliser"><option v-for="power in registered" :key="power.id" :value="power.id">{{power.name}}</option></select></label><template v-if="selectedRegistered"><h4>{{selectedRegistered.name}}</h4><p>{{selectedRegistered.cost}} PA<template v-if="selectedRegistered.limit"> · {{limitNames[selectedRegistered.limit]}}</template> · {{durationNames(selectedRegistered.duration)}}<strong v-if="selectedRegistered.used"> · Déjà utilisée sur cette période</strong></p><details v-if="selectedRegistered.notes"><summary>Texte de la capacité</summary><p class="canonical-rule">{{selectedRegistered.notes}}</p></details><ul v-if="selectedRegistered.effects.length"><li v-for="(effect,index) in selectedRegistered.effects" :key="index">{{registeredEffect(effect)}}</li></ul><p v-if="selectedRegistered.context" class="canonical-rule">Condition : {{selectedRegistered.context}}</p><label v-if="['activate','roll','restricted'].includes(selectedRegistered.route)&&selectedRegistered.context" class="check"><input v-model="contextConfirmed" type="checkbox" /> Cette condition est remplie pour cette utilisation</label><label v-if="['activate','roll','restricted'].includes(selectedRegistered.route)&&needsSkill">Compétence concernée<select v-model="registeredSkill" aria-label="Compétence de la capacité"><option v-for="skill in skillOptions(selectedRegistered)" :key="skill.id" :value="skill.id">{{skill.name}}</option></select></label><button v-if="['activate','roll','restricted'].includes(selectedRegistered.route)" :disabled="selectedRegistered.used||selectedPrepared||selectedRegistered.route==='restricted'&&selectedRegistered.id==='extral-crete-de-mosenine'&&(!inCombat||!profile.actionRestrictions?.atRoundStart)||(!contextConfirmed&&!!selectedRegistered.context)||(needsSkill&&!registeredSkill)||state.unconscious||profile.hp<=0" @click="activateRegistered">{{selectedPrepared?'Capacité déjà préparée':'Activer '+selectedRegistered.name+' · '+selectedRegistered.cost+' PA'}}</button><p v-else class="availability-note">{{routeNames[selectedRegistered.route]}}. Le coût, les limites et les effets sont liés à cette action.</p></template></fieldset>
    <p v-if="showEffects&&profile.lightningWounds?.finalDestruction" class="lightning-wound-note" role="status"><strong>Destruction définitive confirmée par le MJ.</strong> Les soins ordinaires et la régénération ne permettent pas de revenir.</p><p v-else-if="showEffects&&profile.lightningWounds?.blockedRegeneration" class="lightning-wound-note" role="status">{{profile.lightningWounds.blockedRegeneration}} PV ne peuvent pas être régénérés jusqu’à la fin de la scène. Les soins externes et la récupération ordinaire restent possibles.</p>
    <fieldset v-if="showTruth&&frenzyCapabilities.length" :disabled="blocked" class="frenzy-entry"><legend>Entrer en Frénésie</legend><label>Capacité possédée<select v-model="frenzyPowerId" aria-label="Capacité de Frénésie"><option v-for="power in frenzyCapabilities" :key="power.id" :value="power.id">{{power.name}} · {{power.access}}</option></select></label><label>Cause<input v-model="frenzyCause" maxlength="300" /></label><label>Impulsion à poursuivre<input v-model="frenzyImpulse" maxlength="300" placeholder="Action ou objectif réel de cette Frénésie" /></label><label class="check"><input v-model="frenzyContext" type="checkbox" /> Les conditions réelles de cette Frénésie sont remplies</label><button :disabled="frenzy?.active||!chosenFrenzy||!powerAllowed(chosenFrenzy,state.revelation)||!frenzyCause.trim()||!frenzyImpulse.trim()||!frenzyContext" @click="enterFrenzy">Entrer en Frénésie{{chosenFrenzy?.id?.includes('fureur_croissante')&&inCombat?' · 1 PA':''}}</button><details v-if="chosenFrenzy"><summary>Texte de la capacité</summary><p class="canonical-rule">{{chosenFrenzy.text}}</p></details></fieldset>
    <fieldset v-if="showEffects&&frenzy?.active" :disabled="blocked" class="frenzy-status"><legend>Frénésie en cours</legend><strong>{{frenzy.impulse}}</strong><p>Tests physiques +{{frenzy.physicalBonus}}<template v-if="frenzy.concentrationPenalty"> · calme/concentration {{frenzy.concentrationPenalty}}</template><template v-if="frenzy.lucid"> · Rage lucide</template>.</p><p v-if="frenzy.fearSuppressed">La Peur est ignorée pendant cette Frénésie ; les blessures et les autres causes de Stress restent prises en compte.</p><p v-if="frenzy.impulseRequired&&inCombat">Au moins 1 PA du round doit poursuivre l’impulsion.</p><label v-if="frenzy.impulseRequired&&inCombat" class="check"><input v-model="pursuesImpulse" type="checkbox" /> Ma prochaine action poursuit cette impulsion</label><label class="check"><input v-model="frenzyCauseGone" type="checkbox" @change="frenzyExitContext=false" /> La cause a disparu</label><label class="check"><input v-model="frenzyExitContext" type="checkbox" /> Les conditions de sortie sont confirmées avec le MJ</label><button :disabled="!frenzyExitContext" @click="act('frenzy-exit',{causeGone:frenzyCauseGone,contextConfirmed:frenzyExitContext})">Tenter de sortir · difficulté {{frenzyCauseGone?12:15}}</button></fieldset>
    <p v-if="showEffects&&frenzy?.survivalFury" class="preparation-status">Furie de survie : +{{frenzy.survivalFury}} au prochain test physique éligible, jusqu’au round {{frenzy.survivalFuryUntil}}.</p>
    <p v-if="showEffects&&frenzy?.fear">Peur : {{frenzy.fear.level===2?'Paniqué':'Tendu'}} · {{frenzy.fear.cause}}<template v-if="frenzy.fearSuppressed"> · ignorée pendant la Frénésie</template>.</p>
    <details v-if="showEffects&&manager" class="behavior-manager"><summary>MJ · Peur & Frénésie</summary><fieldset :disabled="blocked" class="imposed-frenzy"><legend>Frénésie imposée par la situation</legend><label>Origine<select v-model="imposedOrigin"><option value="supernatural">Source surnaturelle</option><option v-if="['garou','khinae'].includes(String(data.truth.nature))" value="khinae">Khinae / Garou</option><option value="augmentic">Crise augmentique</option></select></label><label>Source réelle<input v-model="imposedSource" maxlength="300" /></label><label>Cause<input v-model="imposedCause" maxlength="300" /></label><label>Impulsion<input v-model="imposedImpulse" maxlength="300" /></label><label class="check"><input v-model="imposedContext" type="checkbox" /> Cette situation et ces conditions sont réellement présentes</label><label v-if="imposedOrigin==='augmentic'" class="check"><input v-model="augmenticTrigger" type="checkbox" /> Le déclenchement de la crise augmentique est confirmé</label><button :disabled="frenzy?.active||!imposedSource.trim()||!imposedCause.trim()||!imposedImpulse.trim()||!imposedContext||imposedOrigin==='augmentic'&&!augmenticTrigger" @click="imposedFrenzy(imposedOrigin==='augmentic'?'frenzy-augmentic-resist':'frenzy-enter')">{{imposedOrigin==='augmentic'?'Tester la résistance augmentique':'Appliquer cette Frénésie'}}</button></fieldset><fieldset :disabled="blocked" class="fear-control"><legend>Peur</legend><label>Source réelle<input v-model="fearSource" maxlength="300" /></label><label>Cause<input v-model="fearCause" maxlength="300" /></label><label>État<select v-model.number="fearLevel"><option :value="0">La Peur est terminée</option><option :value="1">Tendu</option><option :value="2">Paniqué</option></select></label><label class="check"><input v-model="fearContext" type="checkbox" /> La source et son effet ont été résolus</label><button :disabled="!fearSource.trim()||!fearCause.trim()||!fearContext" @click="act('fear-set',{sourceId:fearSource.trim(),cause:fearCause.trim(),level:fearLevel,contextConfirmed:fearContext})">Enregistrer la Peur</button></fieldset></details>
    <section v-if="showEffects&&preparedPowers.length" class="effects-section" aria-label="Capacités préparées du personnage"><h3>Capacités préparées</h3><div class="effects-grid"><article v-for="power in preparedPowers" :key="power.id" class="effect-card"><h4>{{explicitPower(power.id)?.name??'Capacité préparée'}}</h4><p>{{power.period==='test'?'Prochain test éligible':power.period==='scene'?'Jusqu’à la fin de scène':power.period==='scenario'?'Jusqu’à la fin du scénario':'Jusqu’au round '+power.until}}<template v-if="power.skill"> · {{profile.skills.find((s:any)=>s.id===power.skill)?.name}}</template></p><p>{{(explicitPower(power.id)?.effects??[]).map(registeredEffect).join(' · ')}}</p><template v-if="explicitPower(power.id)?.route==='restricted'"><p>Aucune attaque physique ni manipulation lourde. Le bonus concerne seulement la défense active purement physique.</p><label class="check"><input v-model="safeExitConfirmed" type="checkbox" /> Je peux reprendre une forme matérielle ici</label><button :disabled="blocked||!safeExitConfirmed" @click="act('restricted-power-stop',{powerId:power.id,safeExitConfirmed})">Quitter Entre deux états</button></template><button v-else :disabled="blocked" class="secondary" @click="act('power-stop',{powerId:power.id})">Terminer cette capacité · usage conservé</button><p v-if="!registered.some(p=>p.id===power.id)" class="availability-note">La capacité reste suivie, mais ses conditions actuelles ne permettent pas d’appliquer son effet.</p></article></div></section>
    <section v-if="showEffects&&effects.length" class="effects-section" aria-label="Effets suivis du personnage"><h3>Effets actifs</h3><p>Les effets suivent les rounds et les activations de la table. Leurs conditions restent visibles avant chaque action.</p><div class="effects-grid"><article v-for="effect in effects" :key="effect.id" class="effect-card"><h4>{{effect.name??effect.label}}</h4><strong>{{effectValue(effect)}}</strong><p>{{expiry(effect)}}<template v-if="effect.period"> · application au {{periodNames[effect.period]??effect.period}}</template><template v-if="effect.remainingTicks!==null&&effect.remainingTicks!==undefined"> · {{effect.remainingTicks}} application(s) restante(s)</template></p><p v-if="effect.note" class="canonical-rule">{{effect.note}}</p><button v-if="effect.sourceId===effect.targetId" :disabled="blocked" class="secondary" :aria-label="`Terminer l’effet ${effect.name??effect.label}`" @click="act('effect-remove',{effectId:effect.id})">Terminer cet effet</button><p v-else class="availability-note">La suppression de cet effet se résout avec le MJ selon sa règle de soin ou de résistance.</p></article></div></section>
  </div>
</details>
</template>
